// Gzips dist/index.html into the firmware as src/default/html.h.
import { readFileSync, writeFileSync } from "node:fs";
import { gzipSync } from "node:zlib";

const html = readFileSync(new URL("../dist/index.html", import.meta.url));
const gz = gzipSync(html, { level: 9 });
const lines = [];
for (let i = 0; i < gz.length; i += 32) {
    lines.push(Array.from(gz.subarray(i, i + 32), (b) => "0x" + b.toString(16).padStart(2, "0")).join(","));
}
const out =
    "// Generated by firmware-front (npm run build). Do not edit.\n" +
    "#ifndef HTML_H\n#define HTML_H\n\n#include <Arduino.h>\n\n" +
    `#define html_len ${gz.length}\n\n` +
    "const uint8_t html[] PROGMEM = {\n" + lines.join(",\n") + "\n};\n\n#endif\n";
writeFileSync(new URL("../../firmware-back/src/default/html.h", import.meta.url), out);
console.log(`index.html: ${html.length} bytes -> ${gz.length} bytes gzipped -> firmware-back/src/default/html.h`);
